raw:
{
  "spells": [
    {
      "id": "spell_shadow_10",
      "theory": "术者将树脂研成细粉，混入自身魔力后撒向地面，粉末在暗处展开成一片低伏的暗影轮廓。该分影借施术者站姿与动作获得形状，可移动、停驻或模仿简单手势，但不能拾取物品，也不能替人承受全部伤害；实体攻击穿过它时只带走部分魔力，剩余伤害仍由目标承担。",
      "casting": "取一小块树脂在掌心搓碎，屈膝以指节触地，沿地面画出一道短弧，同时低声念出固定音节，使魔力随粉末铺开成形。",
      "failure": "粉末可能只聚成一片模糊暗斑，无法立起分影；或分影出现后立刻散成呛人的树脂烟，让施术者短暂咳嗽、视线受阻，且已消耗的魔力无法收回。",
      "counters": [
        "用强风吹散地面粉末，分影会因失去依附而变淡。",
        "以干燥细沙覆盖暗影轮廓，可让分影暂时无法移动。"
      ],
      "socialConsequences": "河谷乡约允许村民用分影驱赶偷食谷物的鸟兽，但若用来伪装人数吓唬邻居，会被要求当众说明。城中公会不禁止公开演示，却会记录频繁使用者，防止有人借分影在集市制造混乱。琥珀海岸的搬运工讨厌分影混进货堆，因为影子不能搬货，却会让同伴误判人数，港务在事故追责时会调取这类记录。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时分影边缘模糊，走动几步就会自行消散。",
        "熟练后分影能稳定模仿施术者的站姿与简单手势。",
        "再进一步可让分影在指定小片地面上缓慢移动。",
        "高熟练者能精确控制分影出现位置，仍不能拿物或替伤。"
      ]
    },
    {
      "id": "spell_shadow_11",
      "theory": "术者把魔力压入树脂粉末，再将粉末按在无生命材料的表面。魔力沿材料纹理缓慢扩散，使局部变脆、褪色或起层，整个过程会留下与施术者魔力特征相符的暗色纹路，可被追踪。该法术只作用于一处无生命材料，不会自行蔓延到活物或邻近器物，损伤程度受材料质地与施术精度限制。",
      "casting": "捏碎树脂后以拇指按在目标表面，沿材料纹理画一道短直线，保持按压直到粉末渗入，再抬手检查是否留下暗纹。",
      "failure": "材料可能只表面变脏，没有实际损伤；也可能在施术者手中突然碎裂，飞溅的碎屑划伤手指，同时暗色纹路变得极深，使追踪者更容易锁定施术者。",
      "counters": [
        "在目标表面涂一层油脂，可让树脂粉末无法直接接触材料。",
        "用清水反复冲洗暗纹，能削弱追踪所需的魔力痕迹。"
      ],
      "socialConsequences": "河谷里若有人在公共木桥或渡船木料上留下腐蚀印，乡约必令其赔偿并公开道歉。城中公会要求对他人财产施术前取得书面同意，工匠会请施术者先在小块废料上演示，以免损坏成品。琥珀海岸的船主对货箱上的暗纹极为敏感，一旦发现腐蚀印，港务会追查是否有人故意破坏航运货物，并可能按货损追责。",
      "law": {
        "river": "consent",
        "city": "consent",
        "port": "consent"
      },
      "proficiencyEffects": [
        "初学时腐蚀范围难以控制，常留下过大暗斑。",
        "熟练后能只损伤选定的一小块材料表面。",
        "再进一步可让暗纹更浅，但追踪者仍能辨认。",
        "高熟练者能精确控制损伤深度，仍会留下可追查印记。"
      ]
    },
    {
      "id": "spell_shadow_12",
      "theory": "术者以树脂为引，将魔力化作数条细长阴影，从地面缠向目标下肢。阴影本身只具束缚力，但术者可在缠绕同时送入一缕恐惧魔力，使目标感到被黑暗收紧而动作迟疑。该法术需要目标的精神处于可受术状态，若目标明确抗拒或已有精神防护，恐惧部分无法生效，阴影束缚也会减弱。",
      "casting": "将树脂含在舌下，双手在胸前交叉，随后向目标方向张开五指，同时以短促音节驱动阴影从地面升起缠绕。",
      "failure": "阴影可能只缠住目标脚踝便断裂，恐惧魔力反冲回术者，使其双手发冷、心跳加快；也可能阴影完全无法成形，树脂在口中化开，留下苦涩味道，短时间内难以再次施术。",
      "counters": [
        "用强光直照阴影根部，可使缠绕的阴影迅速退缩。",
        "目标剧烈挣扎并大声呼救，会打断术者维持的恐惧魔力。"
      ],
      "socialConsequences": "河谷乡约严禁用此术对付未经同意的路人，若在争执中施展，会被视为精神强迫并交由长老评理。城中公会要求施术前取得精神施法许可，未经许可使用会被记录并限制接取委托。琥珀海岸港务规定，在码头用此术阻碍装卸或船员行动，按妨碍航运处理，若造成货损则追加赔偿，船主与搬运工都会敌视施术者。",
      "law": {
        "river": "permit",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时阴影只能缠住目标片刻，恐惧效果不稳定。",
        "熟练后束缚时间稍长，目标会明显感到动作迟滞。",
        "再进一步可让阴影只缠下肢，较少误触其他部位。",
        "高熟练者能精确控制缠绕力度，仍不能替代精神许可。"
      ]
    }
  ]
}
